      expect(masked).toContain('[REDACTED]');
    });

    it('should mask GitHub tokens', () => {
      const code = 'const token = "ghp_abcdefghijklmnopqrstuvwxyz123456"';
      const masked = maskSecrets(code);
      expect(masked).toContain('[REDACTED]');
    });

    it('should mask AWS keys', () => {
