      const masked = maskSecrets(code);
      expect(masked).toContain('[REDACTED]');
    });

    it('should mask private key headers', () => {
      const code = '-----BEGIN RSA PRIVATE KEY-----\nMIIE...';
      const masked = maskSecrets(code);
      expect(masked).toContain('[REDACTED]');
